/* ❌ OLD: The browser only discovers this font when it parses the
   stylesheet and reaches the @font-face rule. That happens after the
   CSSOM builds — a full round trip after HTML parsing. The font
   arrives late, delaying the text render (FOIT/invisible text) and
   hurting LCP on font-heavy pages. */

@font-face {
  font-family: 'Body';
  src: url('/fonts/body.woff2') format('woff2'); /* ❌ OLD: late discovery */
}

body {
  font-family: 'Body', sans-serif;
}
